# list connected monochrome components, bounding boxes, if solid and >= 5x5
from collections import deque
R=C=30
seen=set(); comps=[]
for i in range(R):
 for j in range(C):
  if (i,j) in seen: continue
  col=grid[i][j]; q=[(i,j)]; seen.add((i,j)); cells=[]
  while q:
   x,y=q.pop(); cells.append((x,y))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<R and 0<=b<C and (a,b) not in seen and grid[a][b]==col:
     seen.add((a,b)); q.append((a,b))
  xs=[x for x,y in cells]; ys=[y for x,y in cells]; h=max(xs)-min(xs)+1; w=max(ys)-min(ys)+1
  if h>=5 and w>=5 and len(cells)==h*w:
   comps.append((col,min(xs),max(xs),min(ys),max(ys),len(cells)))
comps

